function startOfWeekISO(key,weekStart=CALENDAR_WEEK_START){const d=new Date(key+"T00:00:00Z");d.setUTCDate(d.getUTCDate()-((d.getUTCDay()-weekStart+7)%7));return d.toISOString().slice(0,10);}
