function monthGridCells(year,month,weekStart=CALENDAR_WEEK_START){
 const first=new Date(Date.UTC(year,month-1,1));
 const offset=(first.getUTCDay()-weekStart+7)%7;
 const count=new Date(Date.UTC(year,month,0)).getUTCDate();
 const total=Math.ceil((offset+count)/7)*7;
 const cells=Array.from({length:total},(_,i)=>{const d=new Date(Date.UTC(year,month-1,i-offset+1));return {key:d.toISOString().slice(0,10),day:d.getUTCDate(),inMonth:d.getUTCMonth()===month-1};});
 return {offset,cells};
}
