  if(o.onlyMyTargets&&hasTargets&&typeof o.matchesTargets==="function"&&!o.matchesTargets(e,o.targets,o.unitOwners||{}))return false;
  if(typeof o.matchesFilters==="function"&&!o.matchesFilters(e,o.filters))return false;
  if(q&&!(e.university+" "+e.universityId+" "+(e.unit||"")+" "+(e.exam||"")+" "+(e.title||"")+" "+(o.typeLabels&&o.typeLabels[e.type]||"")).normalize("NFKC").toLowerCase().includes(q))return false;
