/* ==== ICS-LOGIC-START (pure RFC 5545 generator, no DOM; unit-tested) ==== */
function icsEscape(s){return String(s??"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n");}
function foldIcsLine(line){
 if(line.length<=70)return line;
 let out="",cur="";
 for(const ch of line){if(cur.length>=70){out+=(out?"\r\n ":"")+cur;cur=ch;}else cur+=ch;}
 if(cur)out+=(out?"\r\n ":"")+cur;
 return out;
}
function toIcsUtc(dateStr,timeStr){
 const ms=Date.parse(dateStr+"T"+timeStr+":00+06:00");
 const d=new Date(ms);
 return d.getUTCFullYear()+String(d.getUTCMonth()+1).padStart(2,"0")+String(d.getUTCDate()).padStart(2,"0")+"T"+String(d.getUTCHours()).padStart(2,"0")+String(d.getUTCMinutes()).padStart(2,"0")+String(d.getUTCSeconds()).padStart(2,"0")+"Z";
}
function toIcsDate(dateStr){return dateStr.replace(/-/g,"");}
function icsAlarmsForEvent(known,offsets,summary){
 const list=Array.isArray(offsets)?offsets:[10080,4320,1440,180];
 return list.map(min=>{
  let trigger="";
  if(known){trigger=min%1440===0?("-P"+(min/1440)+"D"):("-PT"+min+"M");}
  else{
   if(min===180)trigger="PT8H";
   else if(min%1440===0)trigger="-P"+(min/1440)+"D";
   else trigger="-PT"+min+"M";
  }
  return ["BEGIN:VALARM","ACTION:DISPLAY","DESCRIPTION:"+icsEscape(summary),"TRIGGER:"+trigger,"END:VALARM"].map(foldIcsLine).join("\r\n");
 }).join("\r\n");
}
function buildIcsEvent(e,offsets,nowIso){
 const known=evTimeKnown(e),sv=statusView(e),tent=sv.key==="possible"||sv.key==="pending"||!e.verified;
 const baseTitle=e.university+" — "+(e.title||TYPE_LABEL[e.type]||"ভর্তি কার্যক্রম")+(e.unit&&e.unit!=="সকল ইউনিট"?" ("+e.unit+")":"");
 const summary=tent?(baseTitle+" (সম্ভাব্য)"):baseTitle;
 const descParts=[];
 if(!known)descParts.push("সময় প্রকাশিত নয়; অফিসিয়াল সাইটে মিলিয়ে নাও।");
 descParts.push("অবস্থা: "+sv.label);
 if(e.sourceUrl)descParts.push("উৎস: "+e.sourceUrl);
 const desc=descParts.join("\n");
 const stamp=(nowIso||new Date().toISOString()).replace(/[-:]/g,"").replace(/\.\d{3}/,"");
 const lines=["BEGIN:VEVENT","UID:"+e.id+"@bd-admission-calendar.pages.dev","DTSTAMP:"+stamp];
 if(known){
  const startUtc=toIcsUtc(e.date,e.time);
  const endMs=Date.parse(e.date+"T"+e.time+":00+06:00")+3600000;
  const ed=new Date(endMs);
  const endUtc=ed.getUTCFullYear()+String(ed.getUTCMonth()+1).padStart(2,"0")+String(ed.getUTCDate()).padStart(2,"0")+"T"+String(ed.getUTCHours()).padStart(2,"0")+String(ed.getUTCMinutes()).padStart(2,"0")+String(ed.getUTCSeconds()).padStart(2,"0")+"Z";
  lines.push("DTSTART:"+startUtc,"DTEND:"+endUtc);
 }else{
  const endIso=addDaysISO(e.dateEnd||e.date,1);
  lines.push("DTSTART;VALUE=DATE:"+toIcsDate(e.date),"DTEND;VALUE=DATE:"+toIcsDate(endIso));
 }
 lines.push("SUMMARY:"+icsEscape(summary),"DESCRIPTION:"+icsEscape(desc));
 if(e.sourceUrl)lines.push("URL:"+e.sourceUrl);
 const body=lines.map(foldIcsLine).join("\r\n");
 const alarms=icsAlarmsForEvent(known,offsets,summary);
 return body+(alarms?"\r\n"+alarms:"")+"\r\nEND:VEVENT";
}
function buildIcsCalendar(events,offsets,nowIso){
 const head=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//BD Admission Calendar//Vhorti Sohayika//BN","CALSCALE:GREGORIAN","METHOD:PUBLISH"].join("\r\n");
 const body=(events||[]).map(e=>buildIcsEvent(e,offsets,nowIso)).join("\r\n");
 return head+"\r\n"+(body?body+"\r\n":"")+"END:VCALENDAR\r\n";
}
