function miniMonthHtml(){
 const t=dhakaToday(),[y,m]=t.split("-").map(Number),first=new Date(Date.UTC(y,m-1,1)),days=new Date(Date.UTC(y,m,0)).getUTCDate();
 const lead=(first.getUTCDay()+1)%7,names=["শনি","রবি","সোম","মঙ্গল","বুধ","বৃহ","শুক্র"];
 const count={};ADMISSION_EVENTS.filter(e=>!e.conflict&&e.date.slice(0,7)===t.slice(0,7)).forEach(e=>{count[e.date]=(count[e.date]||0)+1;});
 let cells=names.map(n=>'<span class="mm-h" aria-hidden="true">'+n+'</span>').join("")+'<span></span>'.repeat(lead);
 for(let d=1;d<=days;d++){const key=t.slice(0,8)+String(d).padStart(2,"0"),n=count[key]||0;
  cells+='<span class="mm-d'+(key===t?" today":"")+(n?" has":"")+'" role="listitem"'+(key===t?' aria-current="date"':"")+' aria-label="'+d.toLocaleString("bn-BD")+(n?", "+n.toLocaleString("bn-BD")+"টি ইভেন্ট":"")+'">'+d.toLocaleString("bn-BD")+'</span>';}
 return '<section class="rail-card"><h2>'+new Intl.DateTimeFormat("bn-BD",{month:"long",year:"numeric",timeZone:"UTC"}).format(first)+'</h2><div class="mini-month" role="list">'+cells+'</div></section>';
}
