/* ==== STORE-LOGIC-START (pure functions, no DOM; unit-tested) ==== */
const OFFSET_CHOICES=[[10080,"৭ দিন আগে"],[4320,"৩ দিন আগে"],[1440,"২৪ ঘণ্টা আগে"],[180,"৩ ঘণ্টা আগে"]];
const ALLOWED_OFFSETS=OFFSET_CHOICES.map(x=>x[0]);
const V1_EXAM_GROUPS={Engineering:["engineering_university"],Medical:["medical_admission"],General:["general_public_university","admission_cluster"]};
function emptyTargets(){return {groupIds:[],universityIds:[],unitIds:[],eventTypeIds:[]};}
function targetsEmpty(t){return !t||!(t.groupIds.length||t.universityIds.length||t.unitIds.length||t.eventTypeIds.length);}
function cleanIds(list,valid){
 if(!Array.isArray(list))return {ids:[],removed:0};
 const seen=new Set(),ids=[];let removed=0;
 for(const x of list){if(typeof x!=="string"||x.length>80||seen.has(x))continue;seen.add(x);if(valid&&!valid.has(x)){removed++;continue;}if(ids.length<100)ids.push(x);}
 return {ids,removed};
}
function cleanTargets(t,ctx){
 const src=t&&typeof t==="object"?t:{},out=emptyTargets();let removed=0;
 for(const [k,set] of [["groupIds",ctx.groups],["universityIds",ctx.universities],["unitIds",ctx.units],["eventTypeIds",ctx.types]]){const r=cleanIds(src[k],set);out[k]=r.ids;removed+=r.removed;}
 return {targets:out,removed};
}
function matchesTargets(e,t,unitOwner){
 if(targetsEmpty(t))return false;
 const type=!t.eventTypeIds.length||t.eventTypeIds.includes(e.type);
 let scope=true;
 if(t.universityIds.length){
  scope=t.universityIds.includes(e.universityId);
  const mine=t.unitIds.filter(id=>unitOwner[id]===e.universityId);
  if(scope&&mine.length&&e.unitId)scope=mine.includes(e.unitId);
 }else if(t.groupIds.length)scope=t.groupIds.includes(e.institutionGroup);
 return type&&scope;
}
function defaultV2(){return {version:2,theme:"light",onboarding:{done:false,step:0},targets:emptyTargets(),calendar:{view:"list",onlyMyTargets:true,filters:{universityIds:[],unitIds:[],eventTypeIds:[]}},reminders:{offsetsMinutes:ALLOWED_OFFSETS.slice(),push:{enabled:false},filters:{institutionGroupIds:[],universityIds:[],cycleIds:[],unitIds:[],eventTypeIds:[]}},checklist:{}};}
function migrateV1(v1,ctx){
 const o=defaultV2(),p=v1&&typeof v1==="object"?v1:{};
 if(p.theme==="dark")o.theme="dark";
 if(typeof p.favouriteUniversity==="string"&&p.favouriteUniversity)o.targets.universityIds=[p.favouriteUniversity];
 if(p.favouriteUnit&&p.favouriteUniversity){const d=ctx.details.find(x=>x.universityId===p.favouriteUniversity&&x.unit===p.favouriteUnit);if(d)o.targets.unitIds=[d.id];}
 if(V1_EXAM_GROUPS[p.targetExam]&&!o.targets.universityIds.length)o.targets.groupIds=V1_EXAM_GROUPS[p.targetExam].slice();
 const cf=p.calendarFilters;if(cf&&typeof cf==="object")for(const k of ["universityIds","unitIds","eventTypeIds"])o.calendar.filters[k]=cleanIds(cf[k],null).ids;
 const rf=p.reminderFilters;if(rf&&typeof rf==="object")for(const k of Object.keys(o.reminders.filters))o.reminders.filters[k]=cleanIds(rf[k],null).ids;
 o.migratedFrom=1;
 return o;
}
function validateStore(raw,ctx){
 if(!raw||typeof raw!=="object"||Array.isArray(raw))return null;
 if(raw.version===1)return migrateV1(raw,ctx);
 if(raw.version!==2)return null;
 const o=defaultV2();
 o.theme=raw.theme==="dark"?"dark":"light";
 if(raw.onboarding&&typeof raw.onboarding==="object")o.onboarding={done:raw.onboarding.done===true,step:Number.isInteger(raw.onboarding.step)&&raw.onboarding.step>=0&&raw.onboarding.step<=3?raw.onboarding.step:0};
 o.targets=cleanTargets(raw.targets,{groups:null,universities:null,units:null,types:null}).targets;
 if(raw.calendar&&typeof raw.calendar==="object"){
  o.calendar.view=["list","month","week"].includes(raw.calendar.view)?raw.calendar.view:"list";
  o.calendar.onlyMyTargets=raw.calendar.onlyMyTargets!==false;
  const f=raw.calendar.filters;if(f&&typeof f==="object")for(const k of Object.keys(o.calendar.filters))o.calendar.filters[k]=cleanIds(f[k],null).ids;
 }
 if(raw.reminders&&typeof raw.reminders==="object"){
  if(Array.isArray(raw.reminders.offsetsMinutes))o.reminders.offsetsMinutes=ALLOWED_OFFSETS.filter(n=>raw.reminders.offsetsMinutes.includes(n));
  const f=raw.reminders.filters;if(f&&typeof f==="object")for(const k of Object.keys(o.reminders.filters))o.reminders.filters[k]=cleanIds(f[k],null).ids;
 }
 if(raw.checklist&&typeof raw.checklist==="object"&&!Array.isArray(raw.checklist)){
  for(const key of Object.keys(raw.checklist).slice(0,200)){
   const c=raw.checklist[key];if(key.length>100||!c||typeof c!=="object")continue;
   const rec={};for(const s of ["form","fee","admit"])if(c[s]===true)rec[s]=true;
   if(typeof c.updatedAt==="string"&&c.updatedAt.length<=40)rec.updatedAt=c.updatedAt;
   if(Object.keys(rec).length)o.checklist[key]=rec;
  }
 }
 if(raw.migratedFrom===1)o.migratedFrom=1;
 return o;
}
