function setPreference(key,value){state[key]=value;persistPrefs();renderAll();}
function applyTheme(){
 let resolved=state.theme;
 if(resolved!=="dark")resolved="light";
 document.documentElement.dataset.theme=resolved;
 document.documentElement.dataset.palette="green";
 const dark=resolved==="dark";
 document.querySelectorAll(".theme-toggle").forEach(button=>{
  const label=dark?"হালকা মোডে যাও":"গাঢ় মোডে যাও";
  button.innerHTML=(dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.65 17.65l1.42 1.42M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.65 6.35l1.42-1.42"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 15.5A8.5 8.5 0 0 1 8.5 3.5 8.5 8.5 0 1 0 20.5 15.5Z"/></svg>')+(button.hasAttribute("data-label")?"<span>"+(dark?"হালকা মোড":"গাঢ় মোড")+"</span>":"");
  button.setAttribute("aria-label",label);button.setAttribute("aria-pressed",String(dark));button.title=label;
 });
 const meta=document.querySelector('meta[name="theme-color"]');
 if(meta){const bg=getComputedStyle(document.body).backgroundColor||"",m=/rgba\([^)]*,\s*0\)/.test(bg)?null:bg.match(/\d+/g);if(m&&m.length>=3)meta.content="#"+m.slice(0,3).map(n=>Number(n).toString(16).padStart(2,"0")).join("").toUpperCase();}
}

