 if(p==="universities"&&state.universityView==="detail"&&state.selectedUni){const want="universities/"+encodeURIComponent(state.selectedUni)+"/"+(state.uniTab||"overview");if(location.hash.replace(/^#/,"")!==want){location.hash=want;return;}}
