  const icsBulk=e.target.closest("[data-ics-bulk]");if(icsBulk){const list=bulkIcsEvents(),st=$("icsBulkStatus");if(!list.length){if(st)st.textContent="এই মুহূর্তে রপ্তানি করার মতো আসন্ন পাকা তারিখ নেই।";return;}const off=loadV2().reminders.offsetsMinutes;downloadIcsFile("bd-admission-"+dhakaToday()+".ics",buildIcsCalendar(list,off));if(st)st.textContent=list.length.toLocaleString("bn-BD")+"টি ইভেন্টের ক্যালেন্ডার ফাইল নামানো হয়েছে।";return;}
  const day=e.target.closest("[data-select-date]");if(day){state.selectedDate=day.dataset.selectDate;renderCalendar();return;}
