  if(e.target.dataset.filterSearch){const query=e.target.value;state.filterSearch[e.target.dataset.filterSearch]=query;const q=query.normalize("NFKC").toLocaleLowerCase("bn-BD");const panel=e.target.closest(".multi-filter-panel");if(panel)panel.querySelectorAll("[data-filter-option-row]").forEach(row=>{row.hidden=!row.textContent.normalize("NFKC").toLocaleLowerCase("bn-BD").includes(q);});}
