 applyStoredTargets();
 Object.assign(state,{favouriteUniversity:typeof pref.favouriteUniversity==="string"?pref.favouriteUniversity:"",favouriteUnit:pref.favouriteUnit??"",targetExam:pref.targetExam??"",theme:pref.theme==="light"||pref.theme==="dark"?pref.theme:"light",view:["list","month","week"].includes(pref.calendarView)?pref.calendarView:"list",onlyMyTargets:pref.onlyMyTargets!==false,calendarFilters:{universityIds:safeFilterIds(pref.calendarFilters&&pref.calendarFilters.universityIds),unitIds:safeFilterIds(pref.calendarFilters&&pref.calendarFilters.unitIds),eventTypeIds:safeFilterIds(pref.calendarFilters&&pref.calendarFilters.eventTypeIds)},reminderFilters:{institutionGroupIds:safeFilterIds(pref.reminderFilters&&pref.reminderFilters.institutionGroupIds),universityIds:safeFilterIds(pref.reminderFilters&&pref.reminderFilters.universityIds),cycleIds:safeFilterIds(pref.reminderFilters&&pref.reminderFilters.cycleIds),unitIds:safeFilterIds(pref.reminderFilters&&pref.reminderFilters.unitIds),eventTypeIds:safeFilterIds(pref.reminderFilters&&pref.reminderFilters.eventTypeIds)},palette:"green"});
 const date=new Date(todayKey+"T00:00:00Z");
 state.month=date.getUTCMonth()+1;state.year=date.getUTCFullYear();state.selectedDate=todayKey;
